package com.novara.banking.statement;

import com.novara.banking.audit.AuditService;
import com.novara.banking.identity.CurrentIdentity.FederatedIdentity;
import com.novara.banking.shared.DomainException;
import com.novara.banking.statement.StatementModels.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.ResultSet;
import java.time.*;
import java.util.*;

@Service public class StatementService {
 private static final ZoneId BANKING_ZONE=ZoneId.of("Asia/Kolkata"); private final JdbcClient jdbc; private final AuditService audit;
 public StatementService(JdbcClient jdbc,AuditService audit){this.jdbc=jdbc;this.audit=audit;}
 public List<Account> accounts(FederatedIdentity i){return jdbc.sql("SELECT b.public_id,b.masked_number,b.nickname,b.type::text,b.currency FROM bank_accounts b JOIN account_owners o ON o.account_id=b.id JOIN customers c ON c.id=o.customer_id WHERE c.identity_issuer=:issuer AND c.identity_subject=:subject ORDER BY b.created_at,b.id").param("issuer",i.issuer()).param("subject",i.subject()).query((r,n)->new Account(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5))).list();}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Page transactions(FederatedIdentity i,UUID accountId,LocalDate from,LocalDate to,String direction,String type,String search,String sort,int page,int size){validate(from,to,page,size);var a=owned(i,accountId);Instant cutoff=Instant.now();long lineCutoff=cutoffLine();List<Row> all=rows(a.id,from,to,lineCutoff);Summary summary=summarize(accountId,a,from,to,cutoff,lineCutoff,all);var filtered=all.stream().filter(r->direction==null||direction.isBlank()||direction.equals(r.customerDirection())).filter(r->type==null||type.isBlank()||type.equalsIgnoreCase(r.type())).filter(r->search==null||search.isBlank()||(r.description+" "+r.reference).toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT))).toList();List<Row> ordered=new ArrayList<>(filtered);if("oldest".equals(sort))Collections.reverse(ordered);int start=Math.min(page*size,ordered.size()),end=Math.min(start+size,ordered.size());List<Entry> items=ordered.subList(start,end).stream().map(this::entry).toList();return new Page(items,page,size,ordered.size(),(ordered.size()+size-1)/size,summary);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Summary summary(FederatedIdentity i,UUID id,LocalDate from,LocalDate to){validate(from,to,0,50);var a=owned(i,id);Instant cutoff=Instant.now();long lineCutoff=cutoffLine();return summarize(id,a,from,to,cutoff,lineCutoff,rows(a.id,from,to,lineCutoff));}
 @Transactional(isolation=Isolation.REPEATABLE_READ) public Generation generate(FederatedIdentity i,UUID id,LocalDate from,LocalDate to,String key,String correlation){validate(from,to,0,50);if(key==null||!key.matches("[A-Za-z0-9_-]{16,100}"))throw new DomainException(HttpStatus.BAD_REQUEST,"INVALID_IDEMPOTENCY_KEY","A valid Idempotency-Key is required.");var a=owned(i,id);jdbc.sql("SELECT 1 FROM pg_advisory_xact_lock(hashtextextended(:key,0))").param("key",i.subject()+"|STATEMENT|"+key).query(Integer.class).single();var prior=jdbc.sql("SELECT s.public_id,b.public_id,s.period_start,s.period_end,s.accounting_cutoff,s.created_at FROM statement_generations s JOIN bank_accounts b ON b.id=s.account_id WHERE s.customer_id=:c AND s.idempotency_key=:key").param("c",a.customerId).param("key",key).query((r,n)->new Generation(r.getObject(1,UUID.class),"STM-"+r.getObject(1,UUID.class).toString().substring(0,8).toUpperCase(Locale.ROOT),r.getObject(2,UUID.class),r.getObject(3,LocalDate.class),r.getObject(4,LocalDate.class),r.getTimestamp(5).toInstant(),r.getTimestamp(6).toInstant(),"COMPLETED")).optional();if(prior.isPresent()){if(!prior.get().accountId().equals(id)||!prior.get().from().equals(from)||!prior.get().to().equals(to))throw new DomainException(HttpStatus.CONFLICT,"IDEMPOTENCY_KEY_REUSED","The key was used for another statement request.");return prior.get();}Instant cutoff=Instant.now();long lineCutoff=cutoffLine();var rows=rows(a.id,from,to,lineCutoff);var s=summarize(id,a,from,to,cutoff,lineCutoff,rows);String checksum=sha(s+"|"+rows);UUID publicId=UUID.randomUUID();Instant generated=Instant.now();jdbc.sql("INSERT INTO statement_generations(public_id,customer_id,account_id,period_start,period_end,accounting_cutoff,accounting_cutoff_line_id,content_checksum,generation_status,idempotency_key,created_at) VALUES(:p,:c,:a,:f,:t,:cut,:line,:hash,'COMPLETED',:key,:created)").param("p",publicId).param("c",a.customerId).param("a",a.id).param("f",from).param("t",to).param("cut",java.sql.Timestamp.from(cutoff)).param("line",lineCutoff).param("hash",checksum).param("key",key).param("created",java.sql.Timestamp.from(generated)).update();audit.record(i.subject(),"STATEMENT_GENERATED","STATEMENT",publicId,"SUCCESS",correlation,"{\"formatVersion\":2}");return new Generation(publicId,"STM-"+publicId.toString().substring(0,8).toUpperCase(Locale.ROOT),id,from,to,cutoff,generated,"COMPLETED");}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Snapshot snapshot(FederatedIdentity i,UUID generationId){var g=jdbc.sql("SELECT s.public_id,s.period_start,s.period_end,s.accounting_cutoff,s.accounting_cutoff_line_id,s.content_checksum,b.id,b.public_id,b.masked_number,b.type::text,b.currency,c.id,c.display_name FROM statement_generations s JOIN bank_accounts b ON b.id=s.account_id JOIN customers c ON c.id=s.customer_id WHERE s.public_id=:id AND c.identity_issuer=:issuer AND c.identity_subject=:subject").param("id",generationId).param("issuer",i.issuer()).param("subject",i.subject()).query((r,n)->new SnapshotSeed(r.getObject(1,UUID.class),r.getObject(2,LocalDate.class),r.getObject(3,LocalDate.class),r.getTimestamp(4).toInstant(),r.getObject(5,Long.class),r.getString(6),r.getLong(7),r.getObject(8,UUID.class),r.getString(9),r.getString(10),r.getString(11),r.getLong(12),r.getString(13))).optional().orElseThrow(this::notFound);if(g.cutoffLine==null)throw new DomainException(HttpStatus.CONFLICT,"LEGACY_STATEMENT_UNREPRODUCIBLE","This statement predates the immutable ledger cutoff and cannot be safely regenerated.");var a=new Owned(g.accountInternal,g.customerId,g.mask,g.type,g.currency,g.displayName);var rows=rows(a.id,g.from,g.to,g.cutoffLine);var summary=summarize(g.accountPublic,a,g.from,g.to,g.cutoff,g.cutoffLine,rows);if(!sha(summary+"|"+rows).equals(g.checksum))throw new DomainException(HttpStatus.CONFLICT,"STATEMENT_CHECKSUM_MISMATCH","The historical statement failed integrity validation.");return new Snapshot(g.publicId,summary,rows.stream().map(this::entry).toList(),g.displayName);}
 public Receipt receipt(FederatedIdentity i,UUID journalPublicId){return jdbc.sql("SELECT j.public_id,j.journal_reference,j.posted_at,j.description,j.currency,j.status::text,j.reversal_of_journal_id, jl.amount_minor,b.masked_number,jl.direction::text FROM journals j JOIN journal_lines jl ON jl.journal_id=j.id JOIN bank_accounts b ON b.ledger_account_id=jl.ledger_account_id JOIN account_owners o ON o.account_id=b.id JOIN customers c ON c.id=o.customer_id WHERE j.public_id=:id AND j.status IN ('POSTED','REVERSED') AND c.identity_issuer=:issuer AND c.identity_subject=:subject ORDER BY jl.id LIMIT 1").param("id",journalPublicId).param("issuer",i.issuer()).param("subject",i.subject()).query((r,n)->new Receipt(r.getObject(1,UUID.class),r.getString(2),r.getTimestamp(3).toInstant(),r.getObject(7)==null?"POSTED_TRANSACTION":"REVERSAL",r.getLong(8),r.getString(5),"COMPLETED",r.getString(4),"DEBIT".equals(r.getString(10))?r.getString(9):null,"CREDIT".equals(r.getString(10))?r.getString(9):null)).optional().orElseThrow(this::notFound);}
 private List<Row> rows(long account,LocalDate from,LocalDate to,long lineCutoff){Instant start=from.atStartOfDay(BANKING_ZONE).toInstant(),end=to.plusDays(1).atStartOfDay(BANKING_ZONE).toInstant();return jdbc.sql("SELECT j.public_id,j.journal_reference,j.posted_at,j.description,j.currency,j.status::text,j.reversal_of_journal_id,jl.id,jl.direction::text,jl.amount_minor FROM journal_lines jl JOIN journals j ON j.id=jl.journal_id JOIN bank_accounts b ON b.ledger_account_id=jl.ledger_account_id WHERE b.id=:account AND j.status IN ('POSTED','REVERSED') AND j.posted_at>=:start AND j.posted_at<:end AND jl.id<=:line ORDER BY j.posted_at DESC,jl.id DESC").param("account",account).param("start",java.sql.Timestamp.from(start)).param("end",java.sql.Timestamp.from(end)).param("line",lineCutoff).query(this::row).list();}
 private Summary summarize(UUID publicId,Owned a,LocalDate from,LocalDate to,Instant cutoff,long lineCutoff,List<Row> descending){long current=jdbc.sql("SELECT balance_minor FROM ledger_balances lb JOIN bank_accounts b ON b.ledger_account_id=lb.ledger_account_id WHERE b.id=:id").param("id",a.id).query(Long.class).single();long afterCutoff=jdbc.sql("SELECT COALESCE(sum(CASE jl.direction WHEN 'CREDIT' THEN jl.amount_minor ELSE -jl.amount_minor END),0) FROM journal_lines jl JOIN journals j ON j.id=jl.journal_id JOIN bank_accounts b ON b.ledger_account_id=jl.ledger_account_id WHERE b.id=:a AND j.status IN ('POSTED','REVERSED') AND jl.id>:line").param("a",a.id).param("line",lineCutoff).query(Long.class).single();long cutoffBalance=current-afterCutoff;long afterPeriod=jdbc.sql("SELECT COALESCE(sum(CASE jl.direction WHEN 'CREDIT' THEN jl.amount_minor ELSE -jl.amount_minor END),0) FROM journal_lines jl JOIN journals j ON j.id=jl.journal_id JOIN bank_accounts b ON b.ledger_account_id=jl.ledger_account_id WHERE b.id=:a AND j.status IN ('POSTED','REVERSED') AND jl.id<=:line AND j.posted_at>=:end").param("a",a.id).param("line",lineCutoff).param("end",java.sql.Timestamp.from(to.plusDays(1).atStartOfDay(BANKING_ZONE).toInstant())).query(Long.class).single();long close=cutoffBalance-afterPeriod;long credits=descending.stream().filter(r->r.customerDirection().equals("CREDIT")).mapToLong(r->r.amount).sum();long debits=descending.stream().filter(r->r.customerDirection().equals("DEBIT")).mapToLong(r->r.amount).sum();long open=close-credits+debits;long running=close;for(Row r:descending){r.running=running;running-=r.customerDirection().equals("CREDIT")?r.amount:-r.amount;}return new Summary(publicId,a.mask,a.type,a.currency,from,to,cutoff,open,debits,credits,close,descending.size());}
 private long cutoffLine(){return jdbc.sql("SELECT COALESCE(max(jl.id),0) FROM journal_lines jl JOIN journals j ON j.id=jl.journal_id WHERE j.status IN ('POSTED','REVERSED')").query(Long.class).single();}
 private Owned owned(FederatedIdentity i,UUID id){return jdbc.sql("SELECT b.id,c.id,b.masked_number,b.type::text,b.currency,c.display_name FROM bank_accounts b JOIN account_owners o ON o.account_id=b.id JOIN customers c ON c.id=o.customer_id WHERE b.public_id=:id AND c.identity_issuer=:issuer AND c.identity_subject=:subject").param("id",id).param("issuer",i.issuer()).param("subject",i.subject()).query((r,n)->new Owned(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6))).optional().orElseThrow(this::notFound);}
 private Row row(ResultSet r,int n)throws java.sql.SQLException{return new Row(r.getObject(1,UUID.class),r.getString(2),r.getTimestamp(3).toInstant(),r.getString(4),r.getString(5),r.getString(6),r.getObject(7)!=null,r.getLong(8),r.getString(9),r.getLong(10));} private Entry entry(Row r){return new Entry(r.id,r.reference,r.postedAt,r.postedAt.atZone(BANKING_ZONE).toLocalDate(),r.description,r.type(),r.customerDirection().equals("DEBIT")?r.amount:0,r.customerDirection().equals("CREDIT")?r.amount:0,r.running,r.currency,"POSTED",true);}
 private void validate(LocalDate f,LocalDate t,int page,int size){if(f==null||t==null||t.isBefore(f)||f.isBefore(LocalDate.now(BANKING_ZONE).minusMonths(6))||t.isAfter(LocalDate.now(BANKING_ZONE))||page<0||size<1||size>100)throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_STATEMENT_RANGE","Statement dates must be within the last six months and page limits.");}
 private String sha(String value){try{String canonical=value.replaceAll("\\d{4}-\\d{2}-\\d{2}T[^,|\\]]+Z","@instant@");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private DomainException notFound(){return new DomainException(HttpStatus.NOT_FOUND,"DOCUMENT_NOT_FOUND","The requested financial document was not found.");}
 private record Owned(long id,long customerId,String mask,String type,String currency,String displayName){} private record SnapshotSeed(UUID publicId,LocalDate from,LocalDate to,Instant cutoff,Long cutoffLine,String checksum,long accountInternal,UUID accountPublic,String mask,String type,String currency,long customerId,String displayName){} public record Snapshot(UUID id,Summary summary,List<Entry> entries,String customerName){}
 private static final class Row{final UUID id;final String reference;final Instant postedAt;final String description,currency,status,direction;final boolean reversal;final long lineId,amount;long running;Row(UUID id,String reference,Instant postedAt,String description,String currency,String status,boolean reversal,long lineId,String direction,long amount){this.id=id;this.reference=reference;this.postedAt=postedAt;this.description=description;this.currency=currency;this.status=status;this.reversal=reversal;this.lineId=lineId;this.direction=direction;this.amount=amount;}String customerDirection(){return direction;}String type(){return reversal?"REVERSAL":"TRANSFER";}public String toString(){return id+"|"+lineId+"|"+amount+"|"+direction;}}
}
